CREATE TABLE "engineering_evidence_items" (  "id" UUID NOT NULL DEFAULT gen_random_uuid(),  "org_id" UUID NOT NULL,  "project_id" UUID NOT NULL,  "provider" TEXT NOT NULL,  "source_type" TEXT NOT NULL,  "source_sub_type" TEXT NOT NULL,  "evidence_key" TEXT NOT NULL,  "repository_link_id" UUID,  "repository_owner" TEXT,  "repository_name" TEXT,  "branch" TEXT,  "sha" TEXT,  "pull_request_number" INTEGER,  "file_path" TEXT,  "line_start" INTEGER,  "line_end" INTEGER,  "route_method" TEXT,  "route_path" TEXT,  "environment" TEXT,  "actor_github_user_id" TEXT,  "actor_github_login" TEXT,  "mapped_user_id" UUID,  "occurred_at" TIMESTAMPTZ(6),  "status" TEXT NOT NULL DEFAULT 'active',  "confidence" TEXT NOT NULL DEFAULT 'medium',  "severity" TEXT,  "source_url" TEXT,  "provider_raw_id" TEXT,  "title" TEXT,  "summary" TEXT,  "citation_json" JSONB NOT NULL DEFAULT '{}',  "open_target_json" JSONB NOT NULL DEFAULT '{}',  "metadata_json" JSONB NOT NULL DEFAULT '{}',  "archived_at" TIMESTAMPTZ(6),  "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,  "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,  CONSTRAINT "engineering_evidence_items_pkey" PRIMARY KEY ("id"));CREATE TABLE "engineering_evidence_refresh_runs" (  "id" UUID NOT NULL DEFAULT gen_random_uuid(),  "org_id" UUID NOT NULL,  "project_id" UUID NOT NULL,  "started_by_user_id" UUID,  "status" TEXT NOT NULL DEFAULT 'running',  "source_types_json" JSONB NOT NULL DEFAULT '[]',  "counts_json" JSONB NOT NULL DEFAULT '{}',  "warnings_json" JSONB NOT NULL DEFAULT '[]',  "errors_json" JSONB NOT NULL DEFAULT '[]',  "started_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,  "finished_at" TIMESTAMPTZ(6),  "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,  "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,  CONSTRAINT "engineering_evidence_refresh_runs_pkey" PRIMARY KEY ("id"));CREATE TABLE "engineering_evidence_manual_entries" (  "id" UUID NOT NULL DEFAULT gen_random_uuid(),  "org_id" UUID NOT NULL,  "project_id" UUID NOT NULL,  "created_by_user_id" UUID NOT NULL,  "entry_type" TEXT NOT NULL,  "target_kind" TEXT NOT NULL,  "target_ref" TEXT,  "title" TEXT NOT NULL,  "summary" TEXT,  "status" TEXT NOT NULL,  "confidence" TEXT NOT NULL DEFAULT 'medium',  "severity" TEXT,  "citation_json" JSONB NOT NULL DEFAULT '{}',  "open_target_json" JSONB NOT NULL DEFAULT '{}',  "metadata_json" JSONB NOT NULL DEFAULT '{}',  "archived_at" TIMESTAMPTZ(6),  "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,  "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,  CONSTRAINT "engineering_evidence_manual_entries_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "engineering_evidence_project_key" ON "engineering_evidence_items"("project_id", "evidence_key");CREATE INDEX "engineering_evidence_org_project_source_time_idx" ON "engineering_evidence_items"("org_id", "project_id", "source_type", "source_sub_type", "occurred_at");CREATE INDEX "engineering_evidence_project_provider_status_idx" ON "engineering_evidence_items"("project_id", "provider", "status", "updated_at");CREATE INDEX "engineering_evidence_project_repo_branch_idx" ON "engineering_evidence_items"("project_id", "repository_link_id", "branch", "occurred_at");CREATE INDEX "engineering_evidence_project_pr_type_idx" ON "engineering_evidence_items"("project_id", "pull_request_number", "source_sub_type");CREATE INDEX "engineering_evidence_project_file_idx" ON "engineering_evidence_items"("project_id", "file_path");CREATE INDEX "engineering_evidence_project_route_idx" ON "engineering_evidence_items"("project_id", "route_method", "route_path");CREATE INDEX "engineering_evidence_refresh_org_project_status_idx" ON "engineering_evidence_refresh_runs"("org_id", "project_id", "status", "created_at");CREATE INDEX "engineering_manual_org_project_type_status_idx" ON "engineering_evidence_manual_entries"("org_id", "project_id", "entry_type", "status");CREATE INDEX "engineering_manual_project_target_idx" ON "engineering_evidence_manual_entries"("project_id", "target_kind", "target_ref");ALTER TABLE "engineering_evidence_items" ADD CONSTRAINT "engineering_evidence_items_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "engineering_evidence_items" ADD CONSTRAINT "engineering_evidence_items_project_id_fkey" FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "engineering_evidence_items" ADD CONSTRAINT "engineering_evidence_items_repository_link_id_fkey" FOREIGN KEY ("repository_link_id") REFERENCES "github_repository_project_links"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "engineering_evidence_items" ADD CONSTRAINT "engineering_evidence_items_mapped_user_id_fkey" FOREIGN KEY ("mapped_user_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "engineering_evidence_refresh_runs" ADD CONSTRAINT "engineering_evidence_refresh_runs_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "engineering_evidence_refresh_runs" ADD CONSTRAINT "engineering_evidence_refresh_runs_project_id_fkey" FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "engineering_evidence_manual_entries" ADD CONSTRAINT "engineering_evidence_manual_entries_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "engineering_evidence_manual_entries" ADD CONSTRAINT "engineering_evidence_manual_entries_project_id_fkey" FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "engineering_evidence_manual_entries" ADD CONSTRAINT "engineering_evidence_manual_entries_created_by_user_id_fkey" FOREIGN KEY ("created_by_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;